import sys
sys.path.append('/app/skills/search-restaurants/scripts')
from search_restaurants import Restaurants

rests = Restaurants()

cuisines = ['American','Mediterranean','Chinese','Italian']

def top_by_cuisine(city, cuisine, n=3):
    df = rests.run(city)
    if isinstance(df, str):
        return []
    matches = df[df['Cuisines'].str.contains(cuisine, case=False, na=False)].copy()
    if matches.empty:
        return []
    matches = matches.sort_values(by=['Aggregate Rating','Average Cost'], ascending=[False, True])
    return matches.head(n)[['Name','Cuisines','Aggregate Rating','Average Cost']]

for city in ['Cleveland','Columbus','Cincinnati','Minneapolis']:
    print('\n', city)
    for cuisine in cuisines:
        top = top_by_cuisine(city, cuisine)
        if len(top):
            print('\n', cuisine)
            print(top.to_string(index=False))
